/** Every model id, in picker order (featured first). */
export const APISROUTER_MODEL_IDS: string[] = APISROUTER_MODELS.map((m) => m.id)

/** All models, cheapest typical turn first. */
export const APISROUTER_MODELS_BY_PRICE: ApisRouterModel[] = [...APISROUTER_MODELS].sort(
  (a, b) =>
    (a.estimatedTurnCostUsd ?? Number.POSITIVE_INFINITY) - (b.estimatedTurnCostUsd ?? Number.POSITIVE_INFINITY) ||
    (a.inputPer1M ?? Number.POSITIVE_INFINITY) - (b.inputPer1M ?? Number.POSITIVE_INFINITY) ||
    a.id.localeCompare(b.id),
)

/** Every model id, cheapest first. */
export const APISROUTER_MODEL_IDS_BY_PRICE: string[] = APISROUTER_MODELS_BY_PRICE.map((m) => m.id)

